import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.CfwCq2QB.js";const r="/dev-go-docs/shots/0.2.3/en/light/newtab.png",m=JSON.parse('{"title":"New tab","description":"","frontmatter":{},"headers":[],"relativePath":"en/features/newtab.md","filePath":"en/features/newtab.md"}'),s={name:"en/features/newtab.md"};function i(d,e,c,l,h,u){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="new-tab" tabindex="-1">New tab <a class="header-anchor" href="#new-tab" aria-label="Permalink to &quot;New tab&quot;">​</a></h1><p>In one line: search engines with bang syntax (like <code>!gh</code>), search suggestions aggregated from quick links and bookmarks, categorized quick links, and dynamic backgrounds.</p><h2 id="search-engines-and-bangs" tabindex="-1">Search: engines and bangs <a class="header-anchor" href="#search-engines-and-bangs" aria-label="Permalink to &quot;Search: engines and bangs&quot;">​</a></h2><p>The box searches with the current engine by default; type <code>!bang query</code> to switch engines just for that one search:</p><table tabindex="0"><thead><tr><th>Type</th><th>Searches with</th></tr></thead><tbody><tr><td><code>!gh react</code></td><td>GitHub</td></tr><tr><td><code>!npm vite</code></td><td>npm</td></tr><tr><td><code>!mdn fetch</code></td><td>MDN</td></tr><tr><td><code>!so cors error</code></td><td>Stack Overflow</td></tr><tr><td><code>!g keywords</code> / <code>!bd keywords</code> / <code>!b keywords</code></td><td>Google / Baidu / Bing</td></tr></tbody></table><p>As you type, suggestions aggregate your <strong>quick links and browser bookmarks</strong> — frequent sites surface without opening the bookmarks bar.</p><h2 id="quick-links" tabindex="-1">Quick links <a class="header-anchor" href="#quick-links" aria-label="Permalink to &quot;Quick links&quot;">​</a></h2><ul><li>Five preset categories — <strong>Favorites / Dev / AI / Community / Tools</strong> — double-click a category name to rename it</li><li>Hover any site card: edit, delete, or <strong>pin it below the search box</strong> (the pinned row has a cap and tells you when it&#39;s full)</li><li>Adding a site is name + URL + category</li></ul><p>Quick links support <strong>JSON import / export</strong> — move them between machines or keep layouts in sync; duplicates are skipped on import. Default links for fresh installs improve over releases (dead links get removed); anything you&#39;ve edited yourself is never overwritten.</p><h2 id="background-and-theme" tabindex="-1">Background and theme <a class="header-anchor" href="#background-and-theme" aria-label="Permalink to &quot;Background and theme&quot;">​</a></h2><ul><li><strong>Dynamic backgrounds</strong>: 12 shader effects — mesh, neuro, simplex, smoke, metaballs, and more — set to &quot;Random&quot; (a new one each time) or &quot;Fixed&quot;</li><li><strong>Color theme</strong>: Light / Dark / Auto; Auto means dark from 18:00 to 6:00, shared with the popup, settings, and side panel</li></ul><img src="'+r+'" alt="New tab"><p><em>The new tab: search with bangs, categorized quick links, dynamic background.</em></p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>Quick links and proxy configuration <a href="/dev-go-docs/en/settings/sync.html">sync across devices</a> with your browser account; sync storage has a cap (100KB on Chrome) and very large link sets may be asked to slim down</li></ul>',15)])])}const b=t(s,[["render",i]]);export{m as __pageData,b as default};
